  if((a.careers||[]).length>1)out.push(question('primary','WHICH PART OF YOUR CAREER GETS THE FIRST PLAN?',a.careers.filter(x=>roles[x]).map(x=>[x,roles[x].label]),'Choose the current focus without discarding other work.',{note:'You can build and save another plan for another part of your career.'}));
  if(!role)return out.map(q=>approvedQuestion(q,a));
  out.push(question('goal','WHAT WOULD MAKE THE NEXT 30 DAYS WORTH IT?',goals,'Set one measurable starting priority.',{note:'Pick one to start with. We are not fixing your entire life by Tuesday.'}));
  out.push(question('load',role==='owner'||role==='manager'?'HOW BUSY IS THE SALON RIGHT NOW?':'HOW MUCH PAID WORK DO YOU HAVE RIGHT NOW?',[
   ['starting','Starting or rebuilding. Not much paid work yet.'],['open','Some work. Plenty of room for more.'],['busy','Busy, with some room.'],['full','Full, or close to it.'],unknown
  ],'Distinguish building demand from improving existing work.'));
