  const labels={clients:a.load==='full'?'BETTER-FIT WORK. NOT A BIGGER PILE OF IT.':'MAKE THE NEXT BOOKING EASIER TO SAY YES TO.',money:employee?'MAKE THE WORK AND THE PAY MATCH.':'MAKE THE WORK PAY FOR THE TIME IT TAKES.',return:role==='bridal'?'LET A GOOD EVENT LEAD TO THE NEXT ONE.':'GIVE GOOD WORK A NEXT APPOINTMENT.',keep:'FIND WHAT THE BIG NUMBER IS HIDING.',time:'YOUR CALENDAR DOES NOT GET CUSTODY OF YOUR LIFE.',stable:'BUILD A BUSINESS THAT CAN HANDLE A WEIRD WEEK.'};
  let baseline=goal==='clients'?'For '+count+' recent inquiries, note where they came from and whether they became paid work.':goal==='return'?'Choose '+count+' past clients or buyers who could reasonably return or refer someone. Note what actually happened.':goal==='time'?'Record one normal workday, including prep, travel, messages, and cleanup. Keep the pay for that same day beside it.':goal==='stable'?'Check the bills due before your next payment and the money actually available. Keep money owed to you separate.':employee?'Use one actual pay period. Record the pay, all required hours, and work costs you personally paid.':'Use one normal '+profile.unit+'. Record earned pay, the costs you paid, and all the time the work took.';
  if(role==='owner'&&(goal==='money'||goal==='keep'))baseline='Use one normal salon day or month. Keep collected income, payroll, rent, products, fees, and what you paid yourself separate.';
